SELECT


    "${field}"


FROM "${table}"







                    AND "${f.field}" = #{f.value1}



                    AND "${f.field}" > #{f.value1}



                    AND "${f.field}" >= #{f.value1}



                    AND "${f.field}" < #{f.value1}



                    AND "${f.field}" <= #{f.value1}



                    AND "${f.field}"
                    LIKE CONCAT('%', #{f.value1}, '%')



                    AND "${f.field}"
                    BETWEEN #{f.value1}
                    AND #{f.value2}



                    AND "${f.field}"::time
                    BETWEEN CAST(#{f.value1} AS time)
                    AND CAST(#{f.value2} AS time)








    ORDER BY "${orderBy}"



            DESC


            ASC




LIMIT #{limit}
